#pragma once
#include <stdint.h>

// Settings-screen title icon: Clawd-Still (see clawd_still.h) with a
// wrench overlaid on the mascot's right side (no backdrop plate),
// positioned high enough that the canvas height matches the mascot's own
// natural height rather than growing taller to fit the wrench — this does
// mean the wrench partially covers the right eye. Wrench bounding box is
// ~60% of the total canvas area — the dominant element, mascot secondary.
//
// Two sizes, matching this file's small/large icon convention elsewhere
// (see CLAWD_STILL vs CLAWD_STILL_SMALL) — a fixed-pixel-size icon
// rendered unscaled looks proportionally far bigger on a small low-res
// panel than a large one, confirmed on real CYD hardware (an early
// large-only version overran the title row and pushed "Settings" text
// off-screen there; a first small-tier attempt at half the large size,
// 93x64, was still ~2x too big). ui.cpp picks between them via
// L.small_icons, same as every other small/large icon pair in this file.
// CLAWD_SETTINGS_SMALL_* (48x32, matching CLAWD_STILL_SMALL's own
// dimensions exactly) is hand-drawn directly at final size — a first pass
// at a 48x48 square crop dropped both eyes and both arms (evident on
// comparison against CLAWD_STILL_SMALL, the mascot already shown
// elsewhere on the same small-tier boards); this version keeps them.
// Sized against font_styrene_20's line_height (21px, the small-tier
// "Settings" title font): roughly 1.5x that height reads as a proper icon
// next to the text without dwarfing it.
//
// CLAWD_SETTINGS_* (large) has its wrench cropped from a user-supplied
// pixel-art reference sheet
// (gears-cogwheel-wrench-pixel-art-set-...-8-bit-sprite_418367-329-542068135.jpg,
// repo root at the time this was made, not otherwise part of this
// project — a licensed/stock pixel-art asset, not Anthropic-sourced),
// then: background removed (alpha threshold tight enough to avoid an
// anti-aliased color halo at the edges), re-quantized to its own actual
// 4-color palette (navy outline / mid-blue shadow / teal body / cyan
// highlight — sampled from the source, not guessed), and a 5x5 mode
// filter (two passes) applied to both the color and alpha planes to strip
// speckling from a semi-transparent watermark baked into the source image
// — a first attempt at 3x3/one pass left visible speckle on real
// hardware, confirmed via a device screenshot. Resampled directly from
// that cleaned high-res version to keep detail. Source PNGs:
// assets/logo_settings_187x128.png (large) — regenerate its array with
// tools/png_to_lvgl.js (or the ad hoc Python RGB565A8 encoder used to
// originally produce it, if node isn't available) if that badge needs to
// change. assets/logo_settings_48x32.png (small, matching CLAWD_STILL_SMALL's
// own dimensions) is hand-drawn directly at final size — no separate
// cropping/cleanup pipeline; regenerate its array the same way if it
// changes.

#define CLAWD_SETTINGS_W 187
#define CLAWD_SETTINGS_H 128
